choose.when:
SELECT count(*) AS units, coalesce(sum(area_sqm), 0) AS units_area_sqm,
       count(*) FILTER (WHERE bedrooms > 0) AS units_with_bedrooms, coalesce(sum(bedrooms), 0) AS bedrooms
FROM theme.sp_unit WHERE floor_key = #{key}

FROM theme.sp_building x
WHERE x.${col} = #{key}
AND (x.name_en ILIKE '%' || #{q} || '%' OR x.building_id = #{q} OR x.building_internal_id::text = #{q} OR x.bdms_building_id::text = #{q})

FROM theme.sp_floor x
WHERE x.${col} = #{key}
AND x.floor_number ILIKE '%' || #{q} || '%'

FROM theme.sp_unit x
WHERE x.${col} = #{key}
AND (x.unit_number ILIKE '%' || #{q} || '%' OR x.classification ILIKE '%' || #{q} || '%')

mapper.select:
SELECT json_build_object('type', 'FeatureCollection', 'features', coalesce(json_agg(f), '[]'::json))::text FROM (
SELECT json_build_object('type', 'Feature', 'id', row_number() OVER (), 'geometry', ST_AsGeoJSON(ST_SimplifyPreserveTopology(x.geom, #{tol}), 5)::json, 'properties', json_build_object('key', x.municipality_code, 'name', x.name_en, 'level', 'municipality', 'cx', ST_X(x.centroid), 'cy', ST_Y(x.centroid))) AS f FROM theme.sp_municipality x
SELECT json_build_object('type', 'Feature', 'id', row_number() OVER (), 'geometry', ST_AsGeoJSON(ST_SimplifyPreserveTopology(x.geom, #{tol}), 6)::json, 'properties', json_build_object('key', x.district_key, 'name', x.name_en, 'level', 'district', 'm', x.municipality_code, 'cx', ST_X(x.centroid), 'cy', ST_Y(x.centroid), 'plots', s.plots, 'buildings', s.buildings, 'units', s.units, 'built', CASE WHEN s.plots > 0 THEN round(s.plots_constructed * 100.0 / s.plots, 1) END)) AS f FROM theme.sp_district x LEFT JOIN theme.sp_node_stat s ON s.level = 'district' AND s.node_key = x.district_key WHERE x.${col} = #{key}
SELECT json_build_object('type', 'Feature', 'id', row_number() OVER (), 'geometry', ST_AsGeoJSON(ST_SimplifyPreserveTopology(x.geom, #{tol}), 6)::json, 'properties', json_build_object('key', x.community_key, 'name', , 'level', 'community', 'cx', ST_X(x.centroid), 'cy', ST_Y(x.centroid), 'plots', s.plots, 'buildings', s.buildings, 'units', s.units, 'built', CASE WHEN s.plots > 0 THEN round(s.plots_constructed * 100.0 / s.plots, 1) END)) AS f FROM theme.sp_community x LEFT JOIN theme.sp_node_stat s ON s.level = 'community' AND s.node_key = x.community_key WHERE x.${col} = #{key}
SELECT json_build_object('type', 'Feature', 'id', row_number() OVER (), 'geometry', ST_AsGeoJSON(x.geom, 7)::json, 'properties', json_build_object('key', x.plot_key, 'name', , 'level', 'plot', 's', x.construction_status, 'u', coalesce(x.primary_use, 'Undefined'), 'area', round(x.area_sqm, 0))) AS f FROM theme.sp_plot x WHERE x.${col} = #{key} AND x.cancel_date IS NULL LIMIT #{limit}
SELECT json_build_object('type', 'Feature', 'id', row_number() OVER (), 'geometry', ST_AsGeoJSON(x.geom, 7)::json, 'properties', json_build_object('key', x.building_key, 'name', , 'level', 'building', 'src', x.source, 'st', x.physical_status, 'u', coalesce(x.primary_use, 'Undefined'), 'fd', x.bdms_floors IS NOT NULL, 'h', round(coalesce(nullif(x.height_m, 0), x.floors_count * 3.5, x.bdms_floors * 3.5, 6)::numeric, 1))) AS f FROM theme.sp_building x WHERE x.${col} = #{key} LIMIT #{limit}
SELECT json_build_object('type', 'Feature', 'id', row_number() OVER (), 'geometry', ST_AsGeoJSON(x.geom, 7)::json, 'properties', json_build_object('key', x.floor_key, 'name', , 'level', 'floor', 'seq', x.floor_seq, 'b', coalesce(x.base_height_m, 0), 't', coalesce(x.base_height_m, 0) + coalesce(nullif(x.floor_height_m, 0), 3))) AS f FROM theme.sp_floor x WHERE x.${col} = #{key} LIMIT #{limit}
SELECT json_build_object('type', 'Feature', 'id', row_number() OVER (), 'geometry', ST_AsGeoJSON(x.geom, 7)::json, 'properties', json_build_object('key', x.unit_key, 'name', , 'level', 'unit', 'floor', x.floor_key, 'c', coalesce(x.classification, x.unit_type, 'Unknown'), 'b', coalesce(x.base_height_m, 0), 't', coalesce(x.base_height_m, 0) + coalesce(nullif(x.floor_height_m, 0), 3) - 0.15)) AS f FROM theme.sp_unit x WHERE x.${col} = #{key} LIMIT #{limit}
SELECT json_build_object('type', 'Feature', 'id', row_number() OVER (), 'geometry', ST_AsGeoJSON(ST_SimplifyPreserveTopology(x.geom, #{tol}), 6)::json, 'properties', json_build_object('key', x.project_id, 'name', coalesce(x.project_name, x.project_id), 'level', 'masterplan', 'stage', x.stage, 'year', x.approval_year, 'dev', x.developer_name)) AS f FROM theme.dev_masterplan x WHERE x.${col} = #{key} ORDER BY x.area_sqm DESC LIMIT #{limit}
SELECT json_build_object('type', 'Feature', 'id', row_number() OVER (), 'geometry', ST_AsGeoJSON(x.geom, 7)::json, 'properties', json_build_object('key', x.site_id, 'name', 'Site ' || x.site_id, 'level', 'site', 'b', coalesce(x.buildings, 0), 'area', round(x.area_sqm, 0))) AS f FROM theme.dev_construction_site x WHERE x.${col} = #{key} LIMIT #{limit}
SELECT json_build_object('type', 'Feature', 'id', row_number() OVER (), 'geometry', ST_AsGeoJSON(x.centroid, 6)::json, 'properties', json_build_object('key', x.project_id, 'name', coalesce(x.project_name, x.project_id), 'level', 'project', 'st', x.status, 'c', x.category, 'd', x.delayed, 'b', round(x.approved_budget, 0))) AS f FROM theme.dev_capital_project x WHERE x.${col} = #{key} AND x.centroid IS NOT NULL LIMIT #{limit}
SELECT json_build_object('type', 'Feature', 'id', row_number() OVER (), 'geometry', ST_AsGeoJSON(x.geom, 6)::json, 'properties', json_build_object('key', x.id, 'name', coalesce(x.name, x.code), 'level', 'busstop', 'code', x.code, 'stop', x.gtfs_id)) AS f FROM theme.ops_bus_stop x WHERE x.${col} = #{key} LIMIT #{limit}
SELECT json_build_object('type', 'Feature', 'id', row_number() OVER (), 'geometry', ST_AsGeoJSON(x.geom, 6)::json, 'properties', json_build_object('key', x.id, 'name', 'Streetlight ' || x.id, 'level', 'streetlight', 'st', x.status, 'n', x.lamp_count)) AS f FROM theme.ops_streetlight x WHERE x.${col} = #{key} LIMIT #{limit}
SELECT json_build_object('type', 'Feature', 'id', row_number() OVER (), 'geometry', ST_AsGeoJSON(x.centroid, 6)::json, 'properties', json_build_object('key', x.category || ':' || x.source_id, 'name', coalesce(x.name_en, x.name_ar), 'level', 'facility', 'c', x.category, 'sub', x.subtype)) AS f FROM theme.ast_facility x WHERE x.${col} = #{key} AND x.centroid IS NOT NULL LIMIT #{limit}
) q
